<?php
namespace Modules\BankingMicrofinance\Http\Controllers\Accounting;
use Illuminate\Routing\Controller;use Illuminate\Http\Request;use Modules\BankingMicrofinance\Entities\ProvisioningRule;use Modules\BankingMicrofinance\Entities\ProvisioningRun;use Modules\BankingMicrofinance\Services\ProvisioningService;
class ProvisioningController extends Controller{public function index(){ $rules=ProvisioningRule::orderBy('days_past_due_from')->get();$runs=ProvisioningRun::latest()->paginate(20); return view('bankingmicrofinance::accounting.provisioning.index',compact('rules','runs'));} public function create(){return view('bankingmicrofinance::accounting.provisioning.form',['rule'=>new ProvisioningRule]);} public function store(Request $r){ProvisioningRule::create($r->all());return redirect()->route('banking.microfinance.accounting.provisioning.index');} public function edit(ProvisioningRule $provisioning){return view('bankingmicrofinance::accounting.provisioning.form',['rule'=>$provisioning]);} public function update(Request $r, ProvisioningRule $provisioning){$provisioning->update($r->all());return back();} public function destroy(ProvisioningRule $provisioning){$provisioning->delete();return back();} public function generate(Request $r, ProvisioningService $s){$loans=json_decode($r->loans_json ?: '[]', true) ?: []; $s->generate($loans,$r->run_date ?: now()->toDateString()); return back()->with('status','Provisioning run generated.');}}
